import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

function App() {
  const [allRatings, setAllRatings] = useState([]);
  const [selectedTeacher, setSelectedTeacher] = useState('');
  const [filteredData, setFilteredData] = useState([]);
  const [period, setPeriod] = useState('all');

  useEffect(() => {
    const data = localStorage.getItem('allRatings');
    if (data) {
      const parsed = JSON.parse(data);
      setAllRatings(parsed);
    }
  }, []);

  useEffect(() => {
    if (!selectedTeacher) return;
    let ratings = allRatings.filter(r => r.teacher === selectedTeacher);
    if (period !== 'all') {
      const days = { week: 7, month: 30 }[period];
      const cutoff = new Date();
      cutoff.setDate(cutoff.getDate() - days);
      ratings = ratings.filter(r => new Date(r.date) >= cutoff);
    }
    const chartData = ratings.map(r => ({
      date: r.date.split(',')[0],
      rating: r.rating
    }));
    setFilteredData(chartData);
  }, [selectedTeacher, period, allRatings]);

  const teachers = [...new Set(allRatings.map(r => r.teacher))];

  const avgAll = allRatings.length
    ? (allRatings.reduce((a, b) => a + b.rating, 0) / allRatings.length).toFixed(2)
    : 0;

  return (
    <div className="container">
      <h1>Аналітика оцінок</h1>

      <p><strong>Загальний середній рейтинг:</strong> {avgAll}</p>
      <p><strong>Усього оцінок:</strong> {allRatings.length}</p>

      <label>Оберіть викладача:</label>
      <select value={selectedTeacher} onChange={e => setSelectedTeacher(e.target.value)}>
        <option value="">-- Виберіть --</option>
        {teachers.map(t => <option key={t} value={t}>{t}</option>)}
      </select>

      <label>Період:</label>
      <select value={period} onChange={e => setPeriod(e.target.value)}>
        <option value="all">Усі</option>
        <option value="week">Останній тиждень</option>
        <option value="month">Останній місяць</option>
      </select>

      {filteredData.length > 0 ? (
        <ResponsiveContainer width="100%" height={300}>
          <LineChart data={filteredData}>
            <CartesianGrid stroke="#ccc" />
            <XAxis dataKey="date" />
            <YAxis domain={[0, 5]} />
            <Tooltip />
            <Line type="monotone" dataKey="rating" stroke="#007bff" />
          </LineChart>
        </ResponsiveContainer>
      ) : (
        <p>Немає даних для відображення.</p>
      )}
    </div>
  );
}

export default App;
